import {validateDiceAction,normalizedDiceWorkspace} from '../../../src/state/diceRollModel.mjs';
/** Original Advanced Dice callable, now on the single owned Firebase/Vite runtime.
 * Only a verified signed-in account can watch its private dice journal.
 * Dice results are exclusively generated by the secure Firebase server. */
export function createFirebaseDiceService({
  auth,db,firestoreSdk,functions,functionsSdk,readCanonical,enabled=false
}){
  if(!auth||!db||!firestoreSdk||!functions||!functionsSdk||
    typeof readCanonical!=='function')throw Error('Verified dice Firebase dependencies required.');
  const flags=Object.freeze({enabled:enabled===true});
  const same=uid=>{if(auth.currentUser?.uid!==uid)throw Error('Account changed.');};
  async function verified(){
    if(!flags.enabled)throw Error('Advanced dice are disabled.');
    const user=auth.currentUser;
    if(!user?.uid)throw Error('Sign in to use Advanced Dice.');
    const profile=await readCanonical(user);same(user.uid);
    if(profile?.uid!==user.uid)throw Error('Account verification failed.');
    return user.uid;
  }
  function watch(onUpdate,onError){
    let alive=true,stop=()=>{};
    (async()=>{
      try{
        const uid=await verified();if(!alive)return;
        const doc=firestoreSdk.doc(db,'users',uid,'diceWorkspace','current');
        stop=firestoreSdk.onSnapshot(doc,snapshot=>{
          if(!alive)return;
          try{same(uid);onUpdate(normalizedDiceWorkspace(snapshot.exists()?snapshot.data():{}));}
          catch(error){onError?.(error);stop();}
        },error=>{if(alive)onError?.(error);});
        if(!alive)stop();
      }catch(error){if(alive)onError?.(error);}
    })();
    return ()=>{alive=false;stop();};
  }
  async function action(input){
    const request=validateDiceAction(input);
    const uid=await verified();
    const fn=functionsSdk.httpsCallable(functions,'asteriaAdvancedDice');
    const result=await fn(request);
    same(uid);
    if(result.data?.ok!==true)throw Error(result.data?.error||'Dice action failed.');
    return result.data;
  }
  return Object.freeze({availability:()=>flags,watch,action});
}
